/// <summary>
/// The class <c>UPSEcoResPricingAttribute</c> is used to denote a pricing attribute impl. by EcoResAttribute.
/// </summary>
internal class UPSPricingAttributeEcoResAttribute extends UPSAbstractPricingAttribute implements UPSIPricingAttribute
{
    private UPSIPricingAttributeProvider attributeProvider;
    private Name name;
    private Name typeName;

}

Method.Source:
[SuppressBPWarning('BPErrorClassNewNotProtected', 'External class should be able to call constructor.')]
public void new(Name _name, Name _typeName, UPSIPricingAttributeProvider _attributeProvider)
{
    this.name = _name;
    this.typeName = _typeName;
    this.attributeProvider = _attributeProvider;
}

public anytype getValueOfAttribute(Common _pricingObject) //_pricingObject == SO,PO,SQ
{
    return this.attributeProvider.getValueOfAttribute(_pricingObject, this);
}

public str getName() // color, product category, customer category, customer classification
{
    return this.name;
}

public Query buildPricingObjectQuery(Query _query, anytype _value, Map _qbdsMap = null)
{
    return this.attributeProvider.buildPricingObjectQuery(_query, this, _value, _qbdsMap);
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    // Do nothing here for customized pricing attribute.
    // Range set in buildPricingObjectQuery().
}
